// A stub runtime, never run. It exists so the stub can be planned as the
// consumer's accepted dependency edge -- which is what keeps `runAfterSettle`'s
// `creates` candidate alive past closure replay; an unaccepted bare import is a
// hazard that opens every domain before any census could refuse it. The
// certifier's private project materializes the consumer alone, so this file is
// never what the census reads either: the call arrives unresolved.
export function onSettled() {
  throw new Error("solid-js stub: not a runtime");
}
